#include <bits/stdc++.h>
using namespace std;
using ll = long long;

void solve(long long N, std::vector<long long> X, std::vector<long long> L)
{
    vector<pair<ll, ll>> robots;
    for (ll i = 0; i < N;i++) {
        robots.emplace_back(X[i] - L[i], X[i] + L[i]);
    }

    sort(begin(robots), end(robots), [](auto&& a, auto&& b) { return a.second < b.second; });

    ll ans = 1;
    ll s = robots[0].second;
    for (auto r : robots) {
        if (s <= r.first) {
            ans++;
            s = r.second;
        }
    }
    cout << ans << endl;
}

